import{_ as a,o,c as t,a5 as s}from"./chunks/framework.BwlBv862.js";const u=JSON.parse('{"title":"SDK de widgets, gateway e limites de overlays","description":"","frontmatter":{"title":"SDK de widgets, gateway e limites de overlays","docId":"developer.overlays","translationKey":"developer.overlays","locale":"pt","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"99d3351859ddb3a3304133f062f68b8e3130416947fc40433dc9c6bffaf85f6a","translationRevision":"172243dd57089b19a14a3aaae7bf9ab8f24a9e40d9c77e5ad26930a9519bbcd5","order":170},"headers":[],"relativePath":"pt/developer/overlays.md","filePath":"pt/developer/overlays.md","lastUpdated":1794611623000}'),i={name:"pt/developer/overlays.md"};function d(r,e,n,l,c,p){return o(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="widget-sdk-gateway-and-overlay-boundaries" tabindex="-1">SDK de widgets, gateway e limites de overlays <a class="header-anchor" href="#widget-sdk-gateway-and-overlay-boundaries" aria-label="Permalink to &quot;SDK de widgets, gateway e limites de overlays {#widget-sdk-gateway-and-overlay-boundaries}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Crie um widget que compartilhe renderização entre prévia local e saída do OBS. Use as ferramentas Vue instaladas e entenda os <a href="./events.html">eventos</a>. A prévia local não precisa de gateway nem credencial de conta. A saída ao vivo de widgets exige o plugin event-gateway instalado separadamente e sua credencial com escopo de widget.</p><h2 id="add-a-template" tabindex="-1">Adicione um modelo <a class="header-anchor" href="#add-a-template" aria-label="Permalink to &quot;Adicione um modelo {#add-a-template}&quot;">​</a></h2><ol><li>Defina um renderizador dentro de <code>WidgetStage</code>; dimensione-o em relação ao elemento pai em vez da área de visualização do navegador.</li><li>Use <code>defineWidget</code> de <code>src/widgets/sdk/template.ts</code>. Forneça seu esquema, envelopes de amostra novos e a fábrica <code>create(search, clock)</code>.</li><li>Retorne um controlador que implemente <code>handleEnvelope</code>, <code>clear</code> e <code>dispose</code>, além da renderização. Use o relógio fornecido para que prévias possam manter amostras e testes possam avançar o tempo.</li><li>Registre-o em <code>sdk/templates.ts</code> e adicione a entrada independente, configuração de compilação, lista de rotas permitidas do gateway e entrada de empacotamento. O registro sozinho não expõe uma URL pública.</li><li>Use o mesmo <code>WidgetHost.vue</code> no editor e no bundle independente; não incorpore HTML do gateway para uma prévia local.</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> widgets</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/task.ts</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> widgets</span></span></code></pre></div><p>Mantenha tokens de texto, padrões de design e campos editáveis no esquema do modelo. Designs são serializados como JSON e URLs copiadas de widgets carregam um instantâneo validado; um salvamento posterior exige copiar uma URL atualizada para o OBS.</p><h2 id="gateway-protocol" tabindex="-1">Protocolo do gateway <a class="header-anchor" href="#gateway-protocol" aria-label="Permalink to &quot;Protocolo do gateway {#gateway-protocol}&quot;">​</a></h2><p><code>src/widgets/shared/gateway-client.ts</code> é responsável por autenticação, assinaturas, heartbeat, reconexão e relato de lacunas. Widgets consomem envelopes canônicos de domínio, não o TikTok diretamente. O endpoint de widgets é <code>/ws/widgets</code>; ele difere da superfície completa de cliente externo do gateway. Analise envelopes pelo analisador compartilhado e preserve limites de credenciais em vez de passar um token completo do gateway pela WebView principal.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>Prévias locais integradas e o SDK de widgets estão implementados. Edição de overlays do Cloud e código de <code>cloud-overlay</code> existem, mas validação real no OBS, cobertura de imagens/fontes ao vivo e aplicação de pacotes mantêm limites. Changes de Overlays é uma continuação ainda não mesclada. Rankings permanece oculto na navegação normal do aplicativo mesmo com código de widget de ranking existente.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recuperação {#recovery}&quot;">​</a></h2><p>Para uma prévia local em branco, inspecione tempo de vida do controlador, padrões do esquema e dimensionamento do palco antes de enfraquecer a política de origem. Para saída ao vivo, inspecione integridade do gateway, credencial do widget e lacunas explícitas. Um teste Chromium sem interface gráfica não comprova aceitação da fonte de navegador do OBS. O <a href="https://github.com/nglmercer/TikTools-app/tree/remake/src/widgets/sdk" target="_blank" rel="noreferrer">SDK de widgets</a> e os testes de protocolo compartilhado são as referências atuais da implementação.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalhes de operação {#operational-details}&quot;">​</a></h2><p>A suíte unitária usa fixtures; Chromium com gateway real exige widgets construídos e checkout externo via <code>TIKTOOLS_PLUGINS_REPO</code>. Sem fonte ela é omitida: informe skip. Execute <code>bun x --no-install playwright test --config src/widgets/playwright.gateway.config.ts</code> para esse limite. Depois confira OBS real, credencial widget, entrega e recuperação com LIVE; Chromium headless não comprova aceitação OBS/nativa.</p>`,15)])])}const g=a(i,[["render",d]]);export{u as __pageData,g as default};
